using UnityEngine;using System.Linq;using System.Text;
public static class InspectPickups{public static string Main(){var s=new StringBuilder();foreach(var n in new[]{"Pick up","Pick Up Bigger","Pick Up Last"}){var g=GameObject.Find(n);if(!g){s.AppendLine("Missing "+n);continue;}s.AppendLine("ROOT "+n+" pos="+g.transform.position+" rot="+g.transform.eulerAngles+" scale="+g.transform.lossyScale);foreach(var t in g.GetComponentsInChildren<Transform>()){if(t.name.Contains("LOD1")||t.name.Contains("LOD2"))continue;var r=t.GetComponent<Renderer>();s.AppendLine(t.name+" local="+t.localPosition+" rot="+t.localEulerAngles+" world="+(r?r.bounds.ToString():"")+" comps="+string.Join(",",t.GetComponents<Component>().Select(c=>c.GetType().Name)));}}return s.ToString();}}
